/* eslint-disable no-empty-pattern */
/* eslint-disable react-refresh/only-export-components */
import { VehicleList } from '@/@types/reducer/petition';
import { getUploadAPI } from '@/services/entrepreneur/VehicleListService';
import { setLoading, useAppDispatch, useAppSelector } from '@/store';
import { Col, Image, message, Row, Spin } from 'antd'
import React, { useCallback, useEffect, useState } from 'react'

interface Props {
  index: number;
  item: VehicleList;
}

const ContentImage: React.FC<Props> = (props) => {
  const { index, item } = props
  const dispatch = useAppDispatch()
  const { loading } = useAppSelector(state => state.layout)
  const [towingImage, setTowingImage] = useState<string>('')
  const [semiImage, setSemiImage] = useState<string>('')
  const [etcImage, setEtcImage] = useState<string>('')
  const [truckDimensionImage, setTruckDimensionImage] = useState<string>('')
  const [semiDimensionImage, setSemiDimensionImage] = useState<string>('')
  const [cargoDimensionImage, setCargoDimensionImage] = useState<string>('')
  const [combinedVehicleImage, setCombinedVehicle] = useState<string>('')
  const [turningRadiusImage, setTurningRadiusImage] = useState<string>('')
  const [highwayDeptPermitImage, setHighwayDeptPermitImage] = useState<string>('')
  const [highwayDeptPermitNumberImage, setHighwayDeptPermitNumberImage] = useState<string>('')
  const [ruralHighwayDeptPermitImage, setRuralHighwayDeptPermitImage] = useState<string>('')
  const [ruralHighwayDeptPermitNumberImage, setRuralHighwayDeptPermitNumberImage] = useState<string>('')

  const extractUrl = useCallback((url: string) => {
    const path = url.split('/upload')[1];
    return path
  }, []);

  const fetchImage = useCallback(async (
    stateType:
      'towing' |
      'semi' |
      'etc' |
      'truck_dimension' |
      'semi_dimension' |
      'cargo_dimension' |
      'combined_vehicle' |
      'turn_radius' |
      'highway_permit' |
      'highway_number' |
      'rural_permit' |
      'rural_number',
    imgUrl: string
  ) => {
    dispatch(setLoading(true))
    try {
      const response = await getUploadAPI(imgUrl)
      if (response.status === 200) {
        const blobFile = new Blob([response.data], { type: response.data.type })
        const url = URL.createObjectURL(blobFile)
        if (stateType === 'towing') {
          setTowingImage(url)
        }
        if (stateType === 'semi') {
          setSemiImage(url)
        }
        if (stateType === 'etc') {
          setEtcImage(url)
        }
        if (stateType === 'truck_dimension') {
          setTruckDimensionImage(url)
        }
        if (stateType === 'semi_dimension') {
          setSemiDimensionImage(url)
        }
        if (stateType === 'cargo_dimension') {
          setCargoDimensionImage(url)
        }
        if (stateType === 'combined_vehicle') {
          setCombinedVehicle(url)
        }
        if (stateType === 'turn_radius') {
          setTurningRadiusImage(url)
        }
        if (stateType === 'highway_permit') {
          setHighwayDeptPermitImage(url)
        }
        if (stateType === 'highway_number') {
          setHighwayDeptPermitNumberImage(url)
        }
        if (stateType === 'rural_permit') {
          setRuralHighwayDeptPermitImage(url)
        }
        if (stateType === 'rural_number') {
          setRuralHighwayDeptPermitNumberImage(url)
        }
      }
    } catch (error) {
      if (error instanceof Error) {
        message.error(error.message)
      } else {
        console.error(error)
      }
    } finally {
      dispatch(setLoading(false))
    }
  }, [dispatch])

  useEffect(() => {
    if (item?.towing_vehicle?.vehicle_picture?.front_rear_url) {
      fetchImage('towing', extractUrl(item?.towing_vehicle?.vehicle_picture?.front_rear_url))
    }
    if (item?.semi_trailer_vehicle?.vehicle_picture?.front_rear_url) {
      fetchImage('semi', extractUrl(item?.semi_trailer_vehicle?.vehicle_picture?.front_rear_url))
    }
    if (item?.etc_vehicle?.vehicle_picture?.front_rear_url) {
      fetchImage('etc', extractUrl(item?.etc_vehicle?.vehicle_picture?.front_rear_url))
    }
    if (item?.truck_dimension_url) {
      fetchImage('truck_dimension', extractUrl(item?.truck_dimension_url))
    }
    if (item?.semi_trailer_dimension_url) {
      fetchImage('semi_dimension', extractUrl(item?.semi_trailer_dimension_url))
    }
    if (item?.cargo_dimension_url) {
      fetchImage('cargo_dimension', extractUrl(item?.cargo_dimension_url))
    }
    if (item?.combined_vehicle_url) {
      fetchImage('combined_vehicle', extractUrl(item?.combined_vehicle_url))
    }
    if (item?.turning_radius_url) {
      fetchImage('turn_radius', extractUrl(item?.turning_radius_url))
    }
    if (item?.highway_dept_permit_url) {
      fetchImage('highway_permit', extractUrl(item?.highway_dept_permit_url))
    }
    if (item?.highway_dept_permit_number_url) {
      fetchImage('highway_number', extractUrl(item?.highway_dept_permit_number_url))
    }
    if (item?.rural_highway_dept_permit_url) {
      fetchImage('rural_permit', extractUrl(item?.rural_highway_dept_permit_url))
    }
    if (item?.rural_highway_dept_permit_number_url) {
      fetchImage('rural_number', extractUrl(item?.rural_highway_dept_permit_number_url))
    }
  }, [item, extractUrl, fetchImage])

  return (
    <Row gutter={[16, 16]}>
      {item?.towing_vehicle?.vehicle_picture?.front_rear_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <Spin spinning={loading}>
            <figure className='h-60 relative overflow-hidden rounded-lg'>
              <Image
                src={towingImage}
                alt={`image + ${index}`}
                width={'100%'}
                height={'100%'}
                className='object-cover object-center'
                fallback='data:image/png;base64,'
              />
              <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
                <div className='block p-3'>
                  <p className='text-white'>รถลากจูง</p>
                </div>
              </section>
            </figure>
          </Spin>
        </Col>
        : null}
      {item?.semi_trailer_vehicle?.vehicle_picture?.front_rear_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <Spin spinning={loading}>
            <figure className='h-60 relative overflow-hidden rounded-lg'>
              <Image
                src={semiImage}
                alt={`image + ${index}`}
                width={'100%'}
                height={'100%'}
                className='object-cover object-center'
                fallback='data:image/png;base64,'
              />
              <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
                <div className='block p-3'>
                  <p className='text-white'>รถกึ่งพ่วง</p>
                </div>
              </section>
            </figure>
          </Spin>
        </Col>
        : null}
      {item?.etc_vehicle?.vehicle_picture?.front_rear_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <Spin spinning={loading}>
            <figure className='h-60 relative overflow-hidden rounded-lg'>
              <Image
                src={etcImage}
                alt={`image + ${index}`}
                width={'100%'}
                height={'100%'}
                className='object-cover object-center'
                fallback='data:image/png;base64,'
              />
              <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
                <div className='block p-3'>
                  <p className='text-white'>เครื่องจักร</p>
                </div>
              </section>
            </figure>
          </Spin>
        </Col>
        : null}
      {item?.truck_dimension_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <figure className='h-60 relative overflow-hidden rounded-lg'>
            <Image
              src={item?.truck_dimension_url}
              alt={`image + ${index}`}
              width={'100%'}
              height={'100%'}
              className='object-cover object-center'
              fallback='data:image/png;base64,'
            />
            <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
              <div className='block p-3'>
                <p className='text-white'>รูปแบบที่แสดงมิติ รถลากจูง</p>
              </div>
            </section>
          </figure>
        </Col>
        : null}
      {item?.semi_trailer_dimension_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <figure className='h-60 relative overflow-hidden rounded-lg'>
            <Image
              src={item?.semi_trailer_dimension_url}
              alt={`image + ${index}`}
              width={'100%'}
              height={'100%'}
              className='object-cover object-center'
              fallback='data:image/png;base64,'
            />
            <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
              <div className='block p-3'>
                <p className='text-white'>รูปแบบที่แสดงมิติ รถกึ่งพ่วง</p>
              </div>
            </section>
          </figure>
        </Col>
        : null}
      {item?.cargo_dimension_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <figure className='h-60 relative overflow-hidden rounded-lg'>
            <Image
              src={item?.cargo_dimension_url}
              alt={`image + ${index}`}
              width={'100%'}
              height={'100%'}
              className='object-cover object-center'
              fallback='data:image/png;base64,'
            />
            <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
              <div className='block p-3'>
                <p className='text-white'>รูปแบบที่แสดงมิติ สินค้า / เครื่องจักร</p>
              </div>
            </section>
          </figure>
        </Col>
        : null}
      {item?.combined_vehicle_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <figure className='h-60 relative overflow-hidden rounded-lg'>
            <Image
              src={item?.combined_vehicle_url}
              alt={`image + ${index}`}
              width={'100%'}
              height={'100%'}
              className='object-cover object-center'
              fallback='data:image/png;base64,'
            />
            <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
              <div className='block p-3'>
                <p className='text-white'>รูปแบบยานพาหนะรวมสิ่งของ</p>
              </div>
            </section>
          </figure>
        </Col>
        : null}
      {item?.turning_radius_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <figure className='h-60 relative overflow-hidden rounded-lg'>
            <Image
              src={item?.turning_radius_url}
              alt={`image + ${index}`}
              width={'100%'}
              height={'100%'}
              className='object-cover object-center'
              fallback='data:image/png;base64,'
            />
            <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
              <div className='block p-3'>
                <p className='text-white'>รูปแบบที่แสดงรัศมีวงเลี่ยว</p>
              </div>
            </section>
          </figure>
        </Col>
        : null}
      {item?.highway_dept_permit_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <figure className='h-60 relative overflow-hidden rounded-lg'>
            <Image
              src={item?.highway_dept_permit_url}
              alt={`image + ${index}`}
              width={'100%'}
              height={'100%'}
              className='object-cover object-center'
              fallback='data:image/png;base64,'
            />
            <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
              <div className='block p-3'>
                <p className='text-white'>เอกสารขออนุญาตจาก ทล.</p>
              </div>
            </section>
          </figure>
        </Col>
        : null}
      {item?.highway_dept_permit_number_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <figure className='h-60 relative overflow-hidden rounded-lg'>
            <Image
              src={item?.highway_dept_permit_number_url}
              alt={`image + ${index}`}
              width={'100%'}
              height={'100%'}
              className='object-cover object-center'
              fallback='data:image/png;base64,'
            />
            <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
              <div className='block p-3'>
                <p className='text-white'>เลขที่ขออนุญาตเดิมจาก ทล.</p>
              </div>
            </section>
          </figure>
        </Col>
        : null}
      {item?.rural_highway_dept_permit_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <figure className='h-60 relative overflow-hidden rounded-lg'>
            <Image
              src={item?.rural_highway_dept_permit_url}
              alt={`image + ${index}`}
              width={'100%'}
              height={'100%'}
              className='object-cover object-center'
              fallback='data:image/png;base64,'
            />
            <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
              <div className='block p-3'>
                <p className='text-white'>เอกสารขออนุญาตจาก ทช.</p>
              </div>
            </section>
          </figure>
        </Col>
        : null}
      {item?.rural_highway_dept_permit_number_url ?
        <Col xs={24} sm={12} md={12} lg={8} xl={12} xxl={8}>
          <figure className='h-60 relative overflow-hidden rounded-lg'>
            <Image
              src={item?.rural_highway_dept_permit_number_url}
              alt={`image + ${index}`}
              width={'100%'}
              height={'100%'}
              className='object-cover object-center'
              fallback='data:image/png;base64,'
            />
            <section className='bg-gradient-to-r from-black absolute bottom-0 left-0 right-0'>
              <div className='block p-3'>
                <p className='text-white'>เลขที่ขออนุญาตเดิมจาก ทช.</p>
              </div>
            </section>
          </figure>
        </Col>
        : null}
    </Row>
  )
}

export default React.memo<Props>(ContentImage)
